{
  "task_category": "public_documentation_generation_fr",
  "doc_path": "docs/TASK_CATALOG_FR.md",
  "title": "Guide de routage des taches pour le skill Mistral Subagent",
  "content": {
    "introduction": "Ce document decrit comment router efficacement les taches vers les modeles Mistral disponibles dans le skill `mistral-subagent-skill`. Il s'appuie sur les capacites validees en laboratoire et fournit des recommandations concretes pour les projets reels (UI, WebGL, CV, narration video).",
    "quand_deleguer_a_mistral": {
      "description": "Le skill `mistral-subagent` est concu pour deleguer des taches textuelles, bornees et verifiables. Voici les cas d'usage prioritaires :",
      "use_cases": [
        "Analyse et triage de commentaires de review (JSON strict)",
        "Extraction structuree de donnees depuis des fichiers ou documents",
        "Generation ou amelioration de templates GitHub (issues, PR)",
        "Critique et reecriture de copies UI/UX pour experiences scroll-driven",
        "Planification de workflows RAG/embeddings multi-projets",
        "Traduction structuree de notes ou documents publics",
        "Transcription audio FR bornee",
        "OCR et extraction de texte depuis des documents scannes",
        "Revue de diff avec generation de findings en JSON",
        "Ideation de tests unitaires bornes",
        "Audit documentaire ou amelioration de documentation"
      ]
    },
    "routage_par_modele": {
      "description": "Les modeles suivants sont disponibles pour le routage. Leur selection depend de la complexite et du type de tache :",
      "models": [
        {
          "model_id": "mistral-small-latest",
          "use_cases": [
            "Taches textuelles simples (traduction, resume, extraction basique)",
            "Tri de commentaires ou filtrage pre-vol",
            "Generation de templates GitHub",
            "Critique UI/UX copy",
            "Quota reporting de delegation"
          ],
          "limitations": "Non adapte pour des taches necessitant une comprehension profonde du code ou des validations strictes."
        },
        {
          "model_id": "mistral-medium-latest",
          "use_cases": [
            "Extraction JSON stricte (brief de maintenance, revue de diff)",
            "Planification RAG/embeddings",
            "OCR et extraction structuree de documents",
            "Ideation de tests unitaires bornes"
          ],
          "limitations": "Moins performant que `mistral-large-latest` pour les taches complexes ou necessitant une validation rigoureuse."
        },
        {
          "model_id": "mistral-large-latest",
          "use_cases": [
            "Taches complexes necessitant une validation stricte (audit documentaire, amelioration de documentation)",
            "Analyse approfondie de code ou de projets",
            "Planification avancee de workflows"
          ],
          "limitations": "Cout et latence plus eleves. Reserve aux taches critiques."
        },
        {
          "model_id": "devstral-latest",
          "use_cases": [
            "Taches liees au developpement (revue de code, generation de snippets)"
          ],
          "limitations": "Specialise pour le code. Non adapte aux taches textuelles ou documentaires."
        },
        {
          "model_id": "codestral-latest",
          "use_cases": [
            "Generation ou amelioration de code (JavaScript, TypeScript, etc.)",
            "Automatisation de taches de developpement"
          ],
          "limitations": "Exclusivement dedie au code. Non adapte aux taches textuelles ou documentaires."
        },
        {
          "model_id": "mistral-ocr-latest",
          "use_cases": [
            "OCR et extraction de texte depuis des images ou PDF",
            "Transcription de documents scannes"
          ],
          "limitations": "Specialise pour l'OCR. Non adapte aux taches textuelles ou de code."
        },
        {
          "model_id": "mistral-embed",
          "use_cases": [
            "Generation d'embeddings pour RAG ou similarite textuelle",
            "Indexation de documents pour recherche"
          ],
          "limitations": "Exclusivement dedie aux embeddings. Non adapte aux taches de generation ou d'analyse."
        },
        {
          "model_id": "mistral-moderation-latest",
          "use_cases": [
            "Moderation de contenu (filtrage de commentaires, detection de toxicite)"
          ],
          "limitations": "Specialise pour la moderation. Non adapte aux taches de generation ou d'analyse."
        },
        {
          "model_id": "voxtral-mini-latest",
          "use_cases": [
            "Transcription audio FR bornee",
            "Synthese de notes audio"
          ],
          "limitations": "Specialise pour l'audio. Non adapte aux taches textuelles ou de code."
        }
      ]
    },
    "capacites_validees": {
      "description": "Les capacites suivantes ont ete validees ou partiellement validees en laboratoire pour ce repo :",
      "validated_capabilities": [
        {
          "capability": "Audit borne de repo public et amelioration documentaire",
          "status": "Partiellement valide",
          "model_used": "mistral-large-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs project-scan --path <path> --output <path>"
        },
        {
          "capability": "Generation/amelioration bornee de templates GitHub (issues, PR)",
          "status": "Partiellement valide",
          "model_used": "mistral-small-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs recommend --task \"Generer un template d'issue pour une feature X\""
        },
        {
          "capability": "Storyboard/prompt planning pour video scroll-driven",
          "status": "Valide",
          "model_used": "mistral-medium-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Planifier un storyboard pour une video scroll-driven de 30 secondes\" --model mistral-medium-latest"
        },
        {
          "capability": "Extraction JSON stricte d'un brief de maintenance repo",
          "status": "Valide",
          "model_used": "mistral-medium-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Extraire les elements a ameliorer dans ce repo\" --context-file <path> --model mistral-medium-latest"
        },
        {
          "capability": "Critique et reecriture UI/UX copy pour experience scroll-driven",
          "status": "Valide",
          "model_used": "mistral-small-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Critiquer et reecrire cette copie UI/UX pour une meilleure clarte\" --context-file <path> --model mistral-small-latest"
        },
        {
          "capability": "Idees de tests unitaires bornes pour le helper",
          "status": "Valide",
          "model_used": "mistral-medium-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Proposer des idees de tests unitaires pour ce helper\" --context-file <path> --model mistral-medium-latest"
        },
        {
          "capability": "Revue de diff simple avec findings JSON",
          "status": "Valide",
          "model_used": "mistral-medium-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Revoir ce diff et generer des findings en JSON\" --context-file <path> --model mistral-medium-latest"
        },
        {
          "capability": "Triage strict de commentaires de review",
          "status": "Valide",
          "model_used": "mistral-small-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Trier ces commentaires de review par priorite\" --context-file <path> --model mistral-small-latest"
        },
        {
          "capability": "Quota reporting de delegation",
          "status": "Valide",
          "model_used": "mistral-small-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Generer un rapport de quota pour les delegations du mois\" --model mistral-small-latest"
        },
        {
          "capability": "Filtrage pre-vol avant delegation",
          "status": "Valide",
          "model_used": "mistral-small-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Filtrer ces taches avant delegation\" --context-file <path> --model mistral-small-latest"
        },
        {
          "capability": "Planification RAG/embeddings multi-projets",
          "status": "Valide",
          "model_used": "mistral-medium-latest",
          "example_command": "node mistral-subagent/scripts/mistral-subagent.mjs project-action --path <path> --goal \"Planifier un workflow RAG pour ce projet\" --output <path>"
        },
        {
